:root:has(.theme--light) .v-tab:not(.v-tab--active) {
  color: #6c6f85 !important;
}
:root:has(.theme--light) svg.logo path {
  fill: #8230ee !important;
}
:root:has(.theme--light) svg.logo path:last-child {
  fill: #0a52e0 !important;
}
:root:has(.theme--light) .v-chip {
  background: #1e66f5;
}
:root:has(.theme--light) .primary--text,
:root:has(.theme--light) .name-vtuber {
  color: #8839ef !important;
}
:root:has(.theme--light) .text-live {
  color: #d20f39;
}
:root:has(.theme--light) .stream-count-chip {
  color: #dce0e8 !important;
}
:root:has(.theme--light) .nav-btn.v-btn--active {
  color: #8839ef !important;
}
:root:has(.theme--light) div.v-sheet.v-alert {
  background: none !important;
  color: #df8e1d !important;
}
:root:has(.theme--light) div.v-sheet.v-alert .v-icon path {
  fill: #df8e1d !important;
}
:root:has(.theme--light) hr {
  border-color: #eff1f5;
}
:root:has(.theme--light) div.v-snack {
  color: #4c4f69;
}
:root:has(.theme--light) div.v-snack div.v-sheet {
  background: #ccd0da !important;
}
:root:has(.theme--light) div.v-snack button.v-btn--text {
  color: #4c4f69 !important;
}
:root:has(.theme--light) div.v-snack button.v-btn--is-elevated.v-btn--has-bg {
  background: #8839ef !important;
  color: #eff1f5;
}
